using System;using System.IO;using System.Reflection;using System.Reflection.Emit;using System.Collections.Generic;using System.Linq;using ElementalHearts;using Verse;
class ScarletTempestRegression {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(ScarletTempestRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static List<MethodBase> Calls(MethodInfo method){var opcodes=typeof(OpCodes).GetFields(BindingFlags.Static|BindingFlags.Public).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)).ToDictionary(o=>(ushort)o.Value);var il=method.GetMethodBody().GetILAsByteArray();var found=new List<MethodBase>();for(int i=0;i<il.Length;){ushort code=il[i++];if(code==254)code=(ushort)(0xfe00|il[i++]);var op=opcodes[code];switch(op.OperandType){case OperandType.InlineMethod:found.Add(method.Module.ResolveMethod(BitConverter.ToInt32(il,i)));i+=4;break;case OperandType.InlineSwitch:int count=BitConverter.ToInt32(il,i);i+=4+4*count;break;case OperandType.InlineNone:break;case OperandType.ShortInlineBrTarget:case OperandType.ShortInlineI:case OperandType.ShortInlineVar:i++;break;case OperandType.InlineVar:i+=2;break;case OperandType.InlineI8:case OperandType.InlineR:i+=8;break;default:i+=4;break;}}return found;}
 static void Run(){
  var seen=new int[8];for(int tick=0;tick<24;tick++){int f=ScarletTempestRules.Frame(tick,24);Check(f>=0&&f<8,"Invalid frame");seen[f]++;Check(ScarletTempestRules.Opacity(tick,24)>0&&ScarletTempestRules.Opacity(tick,24)<=1,"Opacity out of range");}Check(seen.All(n=>n==3),"Eight frames are not each shown for three ticks");Check(ScarletTempestRules.Frame(-1,24)==0&&ScarletTempestRules.Frame(24,24)==7&&ScarletTempestRules.Frame(100,0)==7,"Frame bounds/zero duration");Check(ScarletTempestRules.Opacity(24,24)==0&&ScarletTempestRules.Opacity(30,24)==0,"Tail does not expire");
  var dance=typeof(HediffComp_LightningAbilities).GetMethod("Dance",BindingFlags.Instance|BindingFlags.NonPublic);var calls=Calls(dance);Check(!calls.Any(m=>m.DeclaringType==typeof(MapComponent_Thunderstorm)&&m.Name=="Queue"),"Scarlet still queues a lingering storm");foreach(string name in new[]{"Targets","Profile","Strike"})Check(calls.Any(m=>m.DeclaringType==typeof(LightningCombat)&&m.Name==name),"Shared immediate spin missing "+name);foreach(string name in new[]{"BeginConsume","FinishConsume"})Check(calls.Any(m=>m.DeclaringType==typeof(LightningCharge)&&m.Name==name),"Charged spin lifecycle missing "+name);Check(calls.Any(m=>m.DeclaringType==typeof(ThunderstormVfx)&&m.Name=="Emit"),"Spin visuals not emitted");
  var map=new MapComponent_Thunderstorm(null);Check(!map.Queue(null,IntVec3.Invalid,false)&&!map.Queue(null,IntVec3.Invalid,true),"Legacy storm enqueue remains enabled");Check(Calls(typeof(HediffComp_TempestCircuit).GetMethod("TryCast")).Any(m=>m.DeclaringType==typeof(TempestDragon)&&m.Name=="TryStart"),"Fifth skill does not use its replacement chain attack");

  Check(ThunderstormEvolution.Tuning.danceRadius==5&&ThunderstormEvolution.Tuning.danceCooldown==750&&ThunderstormEvolution.Tuning.dancePhysical==1.1f&&ThunderstormEvolution.Tuning.danceElectrical==1.4f,"Unrequested tuning change");
  Console.WriteLine("PASS: all eight spin frames display for three ticks, with bounded frame/opacity endpoints.");Console.WriteLine("PASS: compiled production Dance uses immediate shared target/strike/charge lifecycle and visual emission, with no storm queue.");Console.WriteLine("PASS: legacy zones are rejected while the fifth skill routes to Tempest Dragon; radius, cooldown and base damage tuning preserved.");Console.WriteLine("LIMIT: headless checks do not execute live combat, native save loading or GPU rendering.");
 }
}
